text:
{"page_han_chars": 189,
 "errors": [
  {"type": "invented", "transcription": "夫屋及其衆寡", "page": "", "context": "減十餘"},
  {"type": "omitted", "transcription": "", "page": "為寒中後為熱", "context": "矣此則初"},
  {"type": "misread", "transcription": "教治正政", "page": "劇為難治", "context": "已上宜瘥反"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "Most of the text is correct, but there is one invented span, one omitted span, and a garbled ending to the double-column note."}

{"page_han_chars": 153,
 "errors": [
  {"type": "invented", "transcription": "物蓋相須為命", "page": "", "context": "不減於姚黃"},
  {"type": "omitted", "transcription": "", "page": "白舊例公判罷", "context": "遇花時吏"},
  {"type": "misread", "transcription": "其配可知", "page": "景免造業", "context": "矣雖殺風"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "The image is clear: column 2 has six invented characters, column 5 is missing six, and column 7 has four misread characters (the page reads 雖殺風景免造業也)."}

{"page_han_chars": 176,
 "errors": [
  {"type": "invented", "transcription": "知為船以濟水", "page": "", "context": "也不備所\n畢"},
  {"type": "omitted", "transcription": "", "page": "而無驚遽之虞", "context": "今是雄者戢翼"},
  {"type": "misread", "transcription": "知篇木而", "page": "匹為鶩正", "context": "之摯匹解者以"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "There are three errors: six characters added after 畢 in column 3, six characters missing from column 5, and four characters misread near the end of column 7. The rest matches the page."}

{"page_han_chars": 300,
 "errors": [
  {"type": "omitted", "transcription": "", "page": "埤雅", "context": "靜緩"},
  {"type": "misread", "transcription": "急狎猿性猓性躁", "page": "猱性躁急猿性丨丨", "context": "靜緩"}
 ],
 "error_chars": 10,
 "verdict": "material",
 "notes": "The small double-column note under 靜緩 (埤雅猱性躁急猿性丨丨) has been scrambled: the source name 埤雅 is missing and 猱 has become 狎/猓. The rest matches the page, apart from the garbled fold-margin text, which is ignored."}

{"page_han_chars": 285,
 "errors": [
  {"type": "invented", "transcription": "病當以十八日", "page": "", "context": "而釋怨其罪"},
  {"type": "omitted", "transcription": "", "page": "師舍其田而芸", "context": "而又與之出"},
  {"type": "misread", "transcription": "哉黃疸黃", "page": "溺貶而去", "context": "資中黃氏曰"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "The transcription adds six characters, leaves out a six-character phrase alluding to Mencius, and garbles four characters; the rest matches the page."}

{"page_han_chars": 190,
 "errors": [
  {"type": "invented", "transcription": "士祭服謂之弁", "page": "", "context": "能治病問之"},
  {"type": "omitted", "transcription": "", "page": "百姓安肯信嚮", "context": "以心意治病也"},
  {"type": "misread", "transcription": "上祭服謂", "page": "木生肥丘", "context": "二進解"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "The final 翁林 seems to be a misreading of the fold-margin label 榆林, so I ignored it as margin text; otherwise, apart from these three errors, the transcription matches the page."}

{"page_han_chars": 142,
 "errors": [
  {"type": "invented", "transcription": "言語甘說臨之", "page": "", "context": "須是有這箇人"},
  {"type": "omitted", "transcription": "", "page": "一箇身體元來", "context": "者猶言自家"},
  {"type": "misread", "transcription": "无實德而", "page": "二我之體", "context": "我之體猶與仁為"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "Three errors: six invented characters in column 3, six characters left out at the end of column 5, and a four-character misreading at the start of the last column."}

{"page_han_chars": 125,
 "errors": [
  {"type": "invented", "transcription": "其後歲歲循習", "page": "", "context": "國有常刑令羣吏"},
  {"type": "omitted", "transcription": "", "page": "其所守之法防", "context": "脩法則使各脩"},
  {"type": "misread", "transcription": "陽亦作萬", "page": "正政事攷", "context": "鄉四郊之吏平教治"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "The page is clear: six characters are invented in column 3, six are omitted in column 5, and four are misread in column 7."}

{"page_han_chars": 172,
 "errors": [
  {"type": "invented", "transcription": "為之倡主於治", "page": "", "context": "莫知所"},
  {"type": "omitted", "transcription": "", "page": "將加已百仞之", "context": "弧矢治矰繳"},
  {"type": "misread", "transcription": "今四國之", "page": "卿上壽賜", "context": "宮太液池中公"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "The transcription adds a phrase before 戰國策, leaves out 將加已百仞之 in column 5, and garbles the end of column 7; the rest of the text matches the page."}

{"page_han_chars": 130,
 "errors": [
  {"type": "misread", "transcription": "在", "page": "群", "context": ""},
  {"type": "omitted", "transcription": "", "page": "宣公", "context": "春秋左氏傳中"},
  {"type": "misread", "transcription": "齧", "page": "牆", "context": "厚斂以雕"},
  {"type": "misread", "transcription": "眞", "page": "寘", "context": "熟殺之"}
 ],
 "error_chars": 5,
 "verdict": "material",
 "notes": "Three single characters are misread (群 in the title, 牆 and 寘), and the reign heading 宣公 is missing; the rest matches the page."}

{"page_han_chars": 149,
 "errors": [
  {"type": "invented", "transcription": "無用之用也今", "page": "", "context": "亦有知憂之"},
  {"type": "omitted", "transcription": "", "page": "不當也既憂之", "context": "象曰甘臨位"},
  {"type": "misread", "transcription": "有用之用", "page": "能既憂之", "context": "而无利耳若"}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "The image is clear. Three spans around 既憂 are wrong: column 2 has an inserted phrase, column 5 is missing a phrase, and column 7 has a phrase replaced; the other columns match the page."}

{"page_han_chars": 160,
 "errors": [
  {"type": "invented", "transcription": "乃絕朔而立公", "page": "", "context": "國伐魯以"},
  {"type": "omitted", "transcription": "", "page": "國之來齊為之", "context": "今四"},
  {"type": "misread", "transcription": "欲納之然", "page": "衛宣死未", "context": ""}
 ],
 "error_chars": 16,
 "verdict": "material",
 "notes": "This is the right page, but the transcription adds a phrase in column 2, leaves out six characters in column 5 and garbles the start of the last column."}
